-- Create "help_feedbacks" table
CREATE TABLE "help_feedbacks" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "document_id" character varying NOT NULL,
  "document_title" character varying NOT NULL,
  "source_hash" character varying NOT NULL,
  "published_version" bigint NOT NULL DEFAULT 0,
  "quote" text NOT NULL DEFAULT '',
  "message" text NOT NULL,
  "request_key" character varying NOT NULL,
  "actor_id" bigint NOT NULL,
  "actor_name" character varying NOT NULL,
  "response" character varying NOT NULL DEFAULT '',
  "responded_by" character varying NOT NULL DEFAULT '',
  "responded_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "help_feedbacks_request_key_key" to table: "help_feedbacks"
CREATE UNIQUE INDEX "help_feedbacks_request_key_key" ON "help_feedbacks" ("request_key");
-- Create index "helpfeedback_actor_id_created_at" to table: "help_feedbacks"
CREATE INDEX "helpfeedback_actor_id_created_at" ON "help_feedbacks" ("actor_id", "created_at");
-- Create index "helpfeedback_document_id_created_at" to table: "help_feedbacks"
CREATE INDEX "helpfeedback_document_id_created_at" ON "help_feedbacks" ("document_id", "created_at");
-- Create "help_supplement_revisions" table
CREATE TABLE "help_supplement_revisions" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "document_id" character varying NOT NULL,
  "version" bigint NOT NULL,
  "action" character varying NOT NULL,
  "markdown" text NOT NULL,
  "source_hash" character varying NOT NULL,
  "summary" character varying NOT NULL,
  "actor_id" bigint NOT NULL,
  "actor_name" character varying NOT NULL,
  "restored_from" bigint NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "helpsupplementrevision_document_id_version" to table: "help_supplement_revisions"
CREATE UNIQUE INDEX "helpsupplementrevision_document_id_version" ON "help_supplement_revisions" ("document_id", "version");
-- Create "help_supplements" table
CREATE TABLE "help_supplements" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "document_id" character varying NOT NULL,
  "version" bigint NOT NULL DEFAULT 0,
  "published_version" bigint NOT NULL DEFAULT 0,
  "draft_markdown" text NOT NULL DEFAULT '',
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "helpsupplement_document_id" to table: "help_supplements"
CREATE UNIQUE INDEX "helpsupplement_document_id" ON "help_supplements" ("document_id");
